  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Ashness Bridge', 'Nejfotografovanější kamenný mostek Anglie nad jezerem Derwentwater, jen kousek od Keswicku po silničce do Watendlath. Ideální první fotozastávka okruhu — motorka na středověkém mostku s panoramatem Skiddaw v zádech.', 54.5758, -3.0900, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ashness%20Bridge,%20Lake%20District%20-%20June%202009.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ashness%20Bridge,%20Lake%20District%20-%20June%202009.jpg"}'::text[], 0),
    (v_route, 'Honister Pass', 'Průsmyk (356 m) s divokou skalní scenérií a břidlicovým dolem Honister Slate Mine na vrcholu. Sjezd k Buttermere patří k nejhezčím kilometrům Lake Districtu — úzký, strmý a mezi zídkami, brzděte s předstihem.', 54.5116, -3.1994, 'https://commons.wikimedia.org/wiki/Special:FilePath/Honister%20Pass.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Honister%20Pass.jpg"}'::text[], 1),
    (v_route, 'Buttermere', 'Tiché jezero sevřené horami Haystacks a High Stile, oblíbené místo horolezce Alfreda Wainwrighta. U jezera je farma se slavnou zmrzlinou a krátká procházka k břehu stojí za protažení nohou.', 54.5417, -3.2766, 'https://commons.wikimedia.org/wiki/Special:FilePath/Buttermere,%20Lake%20District%20-%20June%202009.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Buttermere,%20Lake%20District%20-%20June%202009.jpg"}'::text[], 2),
    (v_route, 'Hardknott Pass', 'Nejstrmější silnice Anglie — sklon až 30 %, vlásenky první rychlostní stupeň a pod vrcholem ruiny římské pevnosti Mediobogdum s výhledem do údolí Eskdale. Jezděte jen za sucha, mokrý asfalt tu umí potrápit i zkušené.', 54.4029, -3.2116, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hardknott%20Pass.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hardknott%20Pass.jpg"}'::text[], 3),
    (v_route, 'Wrynose Pass', 'Dvojče Hardknottu hned za údolím — na vrcholu stojí Three Shire Stone, kde se historicky stýkala tři anglická hrabství. Technická jednoproudka s výhybnami; kdo jede vlevo poprvé, tady si to opravdu osahá.', 54.4160, -3.1130, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wrynose%20Pass.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Wrynose%20Pass.jpg"}'::text[], 4),
    (v_route, 'Restaurace: The Old Stamp House (Ambleside)', 'Michelinskou hvězdou ověnčený podnik v domě, kde úřadoval básník William Wordsworth — moderní kumbrijská kuchyně z lokálních surovin. Na rychlejší oběd poslouží kavárny na hlavní ulici u ikonického Bridge House.', 54.4287, -2.9620, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bridge%20House,%20Ambleside.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bridge%20House,%20Ambleside.jpg"}'::text[], 5),
    (v_route, 'Kirkstone Pass', 'Nejvyšší průsmyk Lake Districtu otevřený celoročně (454 m) s historickým hostincem na vrcholu a výhledem na jezero Windermere. Odbočka „The Struggle" z Ambleside je strmá zkratka pro odvážné.', 54.4700, -2.9265, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kirkstone%20Pass.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kirkstone%20Pass.jpg"}'::text[], 6);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Buttertubs Pass', 'Legendární horská silnice mezi Wensleydale a Swaledale, pojmenovaná po hlubokých vápencových jámách u vrcholu, kam prý farmáři v horku ukládali máslo. Rychlé esíčka, skvělý asfalt a výhledy — jedna z nejlepších motorkářských silnic severní Anglie.', 54.3450, -2.2010, 'https://commons.wikimedia.org/wiki/Special:FilePath/Buttertubs%20Pass.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Buttertubs%20Pass.jpg"}'::text[], 0),
    (v_route, 'Muker (Swaledale)', 'Kamenná vesnička v nejmalebnějším údolí Dales, obklopená loukami se stodolami a zídkami, jak je znáte z pohlednic. V červnu tu kvetou slavné květnaté louky; zastavte na čaj a koláč v místní čajovně.', 54.3776, -2.1390, 'https://commons.wikimedia.org/wiki/Special:FilePath/Muker,%20Swaledale.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Muker,%20Swaledale.jpg"}'::text[], 1),
    (v_route, 'Restaurace: Tan Hill Inn', 'Nejvýše položená hospoda Velké Británie (528 m) uprostřed vřesovišť — vyhlášené pivo, poctivé hospodské jídlo a krb, který prý nevyhasl desítky let. Kultovní zastávka motorkářů; v zimě tu hosty občas zavěje sníh na několik dní.', 54.4426, -2.1631, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tan%20Hill%20Inn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tan%20Hill%20Inn.jpg"}'::text[], 2),
    (v_route, 'Ribblehead Viaduct', 'Monumentální železniční viadukt z roku 1874 s 24 oblouky na trati Settle–Carlisle, tyčící se uprostřed pusté krajiny Three Peaks. Parkoviště je přímo u silnice B6255 — s trochou štěstí přes viadukt zrovna pojede parní vlak.', 54.2107, -2.3703, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ribblehead%20Viaduct.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ribblehead%20Viaduct.jpg"}'::text[], 3),
    (v_route, 'Malham Cove', 'Osmdesátimetrový vápencový amfiteátr s proslulou „dlažbou" na hraně — natáčel se tu i Harry Potter. Od parkoviště ve vsi Malham je to pěšky asi 20 minut; nahoře odměna v podobě výhledu na celé Airedale.', 54.0722, -2.1580, 'https://commons.wikimedia.org/wiki/Special:FilePath/Malham%20Cove.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Malham%20Cove.jpg"}'::text[], 4),
    (v_route, 'Aysgarth Falls', 'Trojice širokých kaskád řeky Ure ve Wensleydale, známá z filmu Robin Hood: Král zbojníků. Krátká zastávka na protažení — vodopády jsou pár minut chůze od parkoviště, nejmohutnější bývají po dešti.', 54.2919, -1.9819, 'https://commons.wikimedia.org/wiki/Special:FilePath/Aysgarth%20Falls.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Aysgarth%20Falls.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Snake Pass (A57)', 'Slavná horská silnice mezi Glossopem a Sheffieldem, vinoucí se přes vřesoviště Bleaklow do výšky 512 m. Dlouhé zatáčky, žádné zídky, jen otevřená pustina — jeden z nejopojnějších úseků Anglie, který ale vyžaduje respekt k počasí.', 53.4326, -1.8560, 'https://commons.wikimedia.org/wiki/Special:FilePath/Snake%20Pass.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Snake%20Pass.jpg"}'::text[], 0),
    (v_route, 'Ladybower Reservoir', 'Přehrada s ikonickými zvonovými přepady, u níž za války trénovali piloti slavné operace Dambusters s poskakující bombou. Silnice A57 vede přímo přes viadukt nad hladinou; parkoviště u hráze zve na krátkou pauzu.', 53.3780, -1.7130, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ladybower%20Reservoir.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ladybower%20Reservoir.jpg"}'::text[], 1),
    (v_route, 'Winnats Pass', 'Dechberoucí vápencová soutěska nad Castletonem — silnice stoupá až 20% sklonem mezi kolmými travnatými věžemi. Krátký, ale nezapomenutelný úsek; v protisměru se tu s autobusem lépe potkává zespoda.', 53.3410, -1.8040, 'https://commons.wikimedia.org/wiki/Special:FilePath/Winnats%20Pass.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Winnats%20Pass.jpg"}'::text[], 2),
    (v_route, 'Castleton a Peveril Castle', 'Kamenné městečko pod normanským hradem Peveril z 11. století, obklopené jeskyněmi, kde se těží unikátní polodrahokam Blue John. Ideální místo na oběd — hospody tu vaří poctivé yorkshirské klasiky.', 53.3436, -1.7767, 'https://commons.wikimedia.org/wiki/Special:FilePath/Peveril%20Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Peveril%20Castle.jpg"}'::text[], 3),
    (v_route, 'Chatsworth House', 'Velkolepé sídlo vévodů z Devonshiru s barokními zahradami a kaskádou — „Pemberley" z Pýchy a předsudku. I bez prohlídky stojí za zastávku průjezd parkem, kde se mezi silnicí a řekou pasou stáda jelenů.', 53.2277, -1.6110, 'https://commons.wikimedia.org/wiki/Special:FilePath/Chatsworth%20House.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Chatsworth%20House.jpg"}'::text[], 4),
    (v_route, 'Matlock Bath', 'Viktoriánské lázně v soutěsce řeky Derwent, o víkendech největší přirozený sraz motorkářů v Anglii — promenáda je lemovaná stovkami strojů, stánky s fish and chips a obchody s vybavením. Nad údolím jezdí lanovka na Heights of Abraham.', 53.1220, -1.5610, 'https://commons.wikimedia.org/wiki/Special:FilePath/Matlock%20Bath.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Matlock%20Bath.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Cat and Fiddle Inn', 'Druhá nejvýše položená hospoda Anglie (515 m), která dala jméno celé silnici A537 — dnes v budově sídlí i palírna whisky Forest Distillery. Tradiční zastávka motorkářů s výhledem přes celý Cheshire až k Walesu.', 53.2437, -1.9967, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20and%20Fiddle%20Inn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20and%20Fiddle%20Inn.jpg"}'::text[], 0),
    (v_route, 'Errwood Reservoir (Goyt Valley)', 'Klidná přehrada v Goytském údolí, kam vede krásná odbočka z hlavního tahu — úzká silnička kolem vody, ruiny sídla Errwood Hall a v červnu kvetoucí rododendrony. Perfektní tichá pauza mezi dvěma slavnými silnicemi.', 53.2740, -1.9950, 'https://commons.wikimedia.org/wiki/Special:FilePath/Errwood%20Reservoir.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Errwood%20Reservoir.jpg"}'::text[], 1),
    (v_route, 'Buxton – The Crescent', 'Gruzínský lázeňský půlměsíc z 18. století, kterým chtěl vévoda z Devonshiru konkurovat Bathu — dnes luxusní lázně a symbol města. Buxtonská minerálka od pramene St Ann je tu k ochutnání zdarma.', 53.2591, -1.9110, 'https://commons.wikimedia.org/wiki/Special:FilePath/The%20Crescent,%20Buxton.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Crescent,%20Buxton.jpg"}'::text[], 2),
    (v_route, 'Restaurace: The Old Hall Hotel (Buxton)', 'Podnik, který se hlásí k titulu nejstaršího hotelu Anglie — nocovala tu i Marie Stuartovna. Skvělá poloha u Opera House a Pavilion Gardens, poctivá britská kuchyně a odpolední čaj pro nemotorizovanou část posádky.', 53.2585, -1.9125, 'https://commons.wikimedia.org/wiki/Special:FilePath/Buxton%20Opera%20House.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Buxton%20Opera%20House.jpg"}'::text[], 3),
    (v_route, 'The Roaches', 'Zubatý gritstonový hřeben nad silnicí A53 u Leeku, ráj horolezců s výhledem na půl Anglie — za jasného dne dohlédnete až na velšské hory. Podle legendy tu v 70. letech žili uprchlí klokani ze soukromého zvěřince.', 53.1650, -1.9930, 'https://commons.wikimedia.org/wiki/Special:FilePath/The%20Roaches.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Roaches.jpg"}'::text[], 4),
    (v_route, 'Shutlingsloe', '„Cheshirský Matterhorn" — nápadný kuželovitý kopec (506 m) nad vesničkou Wildboarclough, kde podle pověsti zabili posledního divočáka v Anglii. Silnička údolím Clough Brook je úzká jednoproudka jako stvořená pro pomalé kochání.', 53.2317, -2.0090, 'https://commons.wikimedia.org/wiki/Special:FilePath/Shutlingsloe.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Shutlingsloe.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Burford', '„Brána do Cotswolds" — středověké městečko, jehož hlavní ulice se svažuje mezi kamennými domy ke starému mostu přes řeku Windrush. Antikvariáty, čajovny a jedna z nejstarších lékáren v Anglii.', 51.8085, -1.6362, 'https://commons.wikimedia.org/wiki/Special:FilePath/Burford%20High%20Street.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Burford%20High%20Street.jpg"}'::text[], 0),
    (v_route, 'Bibury – Arlington Row', 'Řada tkalcovských domků ze 17. století, kterou William Morris označil za nejkrásnější vesnickou scenérii Anglie — najdete ji i v britských pasech. Přijeďte brzy ráno, přes den bývá plno; hned vedle je historická pstruží farma.', 51.7599, -1.8330, 'https://commons.wikimedia.org/wiki/Special:FilePath/Arlington%20Row,%20Bibury.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Arlington%20Row,%20Bibury.jpg"}'::text[], 1),
    (v_route, 'Bourton-on-the-Water', '„Benátky Cotswolds" — mělká říčka Windrush protéká přímo návsí pod nízkými kamennými mostky. K vidění je tu i automobilové muzeum a miniaturní model celé vesnice v měřítku 1:9.', 51.8523, -1.7550, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bourton-on-the-Water.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bourton-on-the-Water.jpg"}'::text[], 2),
    (v_route, 'Stow-on-the-Wold', 'Nejvýše položené městečko Cotswolds s rozlehlým tržním náměstím, kde se křižovaly středověké ovčí stezky. U kostela sv. Edwarda rostou z portálu dva tisy — dveře jako z Pána prstenů.', 51.9300, -1.7220, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stow-on-the-Wold.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stow-on-the-Wold.jpg"}'::text[], 3),
    (v_route, 'Broadway Tower', 'Romantická „bláznivá věž" z roku 1798 na druhém nejvyšším bodě Cotswolds — za jasného dne z ní dohlédnete do třinácti hrabství. Příjezdová silnička po hřebeni je krásná sama o sobě; u věže žije stádo jelenů.', 52.0244, -1.8358, 'https://commons.wikimedia.org/wiki/Special:FilePath/Broadway%20tower%20edit.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Broadway%20tower%20edit.jpg"}'::text[], 4),
    (v_route, 'Restaurace: The Lygon Arms (Broadway)', 'Historický hostinec ze 16. století na hlavní třídě „nejkrásnější vesnice Anglie" — nocoval tu Oliver Cromwell i Karel I. Elegantní grill room s poctivými britskými klasikami; na lehčí oběd poslouží kavárny přímo na Broadway High Street.', 52.0390, -1.8580, 'https://commons.wikimedia.org/wiki/Special:FilePath/Broadway,%20Worcestershire.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Broadway,%20Worcestershire.jpg"}'::text[], 5),
    (v_route, 'Chipping Campden', 'Perla mezi cotswoldskými městečky s obloukovou tržnicí z roku 1627 uprostřed hlavní ulice. Odsud startuje dálková stezka Cotswold Way; kamenné domy tu mají snad nejsytější medový odstín z celé oblasti.', 52.0500, -1.7790, 'https://commons.wikimedia.org/wiki/Special:FilePath/Chipping%20Campden%20High%20Street.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Chipping%20Campden%20High%20Street.jpg"}'::text[], 6);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'St Michael''s Mount', 'Kornwallské dvojče francouzského Mont-Saint-Michel — hradní ostrov, na který se za odlivu dojde pěšky po dlážděné hrázi z Marazionu. Zkontrolujte si časy přílivu; za vysoké vody jezdí přívozní loďky.', 50.1170, -5.4770, 'https://commons.wikimedia.org/wiki/Special:FilePath/St%20Michael''s%20Mount.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/St%20Michael''s%20Mount.jpg"}'::text[], 0),
    (v_route, 'Lizard Point', 'Nejjižnější bod Velké Británie s majákem, tuleni pod útesy a kioskem s krabími sendviči. Poloostrov Lizard má vlastní mikroklima a vzácnou geologii — hadec odsud se brousí na suvenýry už dvě stě let.', 49.9591, -5.2151, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lizard%20Point,%20Cornwall.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lizard%20Point,%20Cornwall.jpg"}'::text[], 1),
    (v_route, 'Mousehole', 'Miniaturní rybářský přístav, o kterém básník Dylan Thomas prohlásil, že je nejkrásnější vesnicí Anglie. Vjezd do přístavu se na zimu zahrazuje trámy proti bouřím; uličky jsou tak úzké, že motorka je tu ideální dopravní prostředek.', 50.0838, -5.5385, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mousehole%20Harbour.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mousehole%20Harbour.jpg"}'::text[], 2),
    (v_route, 'Minack Theatre', 'Divadlo pod širým nebem vytesané do žulového útesu nad tyrkysovou zátokou Porthcurno — z hlediště je vidět na moře a s trochou štěstí i na delfíny. Vybudovala ho vlastníma rukama Rowena Cade ve 30. letech.', 50.0403, -5.6519, 'https://commons.wikimedia.org/wiki/Special:FilePath/Minack%20Theatre.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Minack%20Theatre.jpg"}'::text[], 3),
    (v_route, 'Land''s End', 'Nejzápadnější výběžek Anglie, kde končí silnice a začíná Atlantik — slavný ukazatel s nápisem „John o'' Groats 874 mil" je povinná fotka. Nejhezčí jsou útesy kousek od turistického areálu, směrem k zátoce Sennen.', 50.0664, -5.7147, 'https://commons.wikimedia.org/wiki/Special:FilePath/Land''s%20End.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Land''s%20End.jpg"}'::text[], 4),
    (v_route, 'St Ives', 'Umělecký přístav s plážemi, které by obstály i ve Středomoří, pobočkou galerie Tate a uličkami plnými ateliérů. Pozor na racky — kornwallský pasty nebo zmrzlinu vám umí vytrhnout přímo z ruky.', 50.2110, -5.4800, 'https://commons.wikimedia.org/wiki/Special:FilePath/St%20Ives%20Cornwall.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/St%20Ives%20Cornwall.jpg"}'::text[], 5),
    (v_route, 'Restaurace: The Sloop Inn (St Ives)', 'Přístavní hospoda z roku 1312 přímo na nábřeží — čerstvé ryby, kornwallský ale a stoly, od kterých sledujete rybářské lodě. Jedna z nejstarších hospod v Cornwallu a ideální tečka před návratem do Penzance.', 50.2119, -5.4790, 'https://commons.wikimedia.org/wiki/Special:FilePath/The%20Sloop%20Inn,%20St%20Ives.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Sloop%20Inn,%20St%20Ives.jpg"}'::text[], 6);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Haytor', 'Nejslavnější žulová skalní věž Dartmooru, viditelná až od pobřeží — od parkoviště u silnice je to nahoru jen pár minut. Výhled na celé jižní Devonsko a první setkání s dartmoorskými poníky.', 50.5800, -3.7530, 'https://commons.wikimedia.org/wiki/Special:FilePath/Haytor%20Rocks.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Haytor%20Rocks.jpg"}'::text[], 0),
    (v_route, 'Widecombe-in-the-Moor', 'Vesnička v hlubokém údolí uprostřed vřesovišť s kostelem přezdívaným „katedrála vřesovišť", opěvovaná ve staré lidové písni o jarmarku. Hospoda a čajovna na návsi zvou na devonský cream tea — nejdřív džem, pak smetana, ať nenaštvete místní.', 50.5761, -3.8110, 'https://commons.wikimedia.org/wiki/Special:FilePath/Widecombe-in-the-Moor.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Widecombe-in-the-Moor.jpg"}'::text[], 1),
    (v_route, 'Dartmeet', 'Soutok Východního a Západního Dartu s prastarým kamenným mostem — jedno z nejmalebnějších míst parku. V řece se dá za horkého dne smočit; na parkovišti pozor na poníky, kteří loudí svačiny.', 50.5468, -3.8730, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dartmeet.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dartmeet.jpg"}'::text[], 2),
    (v_route, 'Postbridge – Clapper Bridge', 'Nejzachovalejší středověký „clapper bridge" v Anglii — obří žulové desky přes řeku Dart položené ve 13. století. Stojí hned vedle silnice B3212 a je to nejfotografovanější kamenný most Dartmooru.', 50.5920, -3.9120, 'https://commons.wikimedia.org/wiki/Special:FilePath/Postbridge%20Clapper%20Bridge.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Postbridge%20Clapper%20Bridge.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Two Bridges Hotel (Dartmoor)', 'Historický hostinec z 18. století u brodu přes Západní Dart, uprostřed ničeho a přesně proto dokonalý — krby, devonská kuchyně a vyhlášený cream tea. Ideální oběd v půlce okruhu.', 50.5540, -3.9660, 'https://commons.wikimedia.org/wiki/Special:FilePath/Two%20Bridges%20Hotel.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Two%20Bridges%20Hotel.jpg"}'::text[], 4),
    (v_route, 'Princetown', 'Nejvýše položené městečko Dartmooru, kterému dominuje věznice z napoleonských válek — dnes s muzeem, kde uvidíte i vězeňské výrobky a historii útěků, které inspirovaly Conana Doyla. Návštěvnické centrum parku sídlí v hotelu, kde Pes baskervillský vznikal.', 50.5450, -3.9920, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dartmoor%20Prison.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dartmoor%20Prison.jpg"}'::text[], 5),
    (v_route, 'Brent Tor', 'Kostelík sv. Michaela z 13. století na vrcholu osamělého sopečného suku na západním okraji Dartmooru — jedna z nejdramatičtějších siluet Devonu. Krátký výšlap od parkoviště odmění výhledem od Plymouth Sound až po Bodmin Moor.', 50.6053, -4.1600, 'https://commons.wikimedia.org/wiki/Special:FilePath/Brentor%20Church.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Brentor%20Church.jpg"}'::text[], 6);
