  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Hadriánův val – Housesteads', 'Nejzachovalejší římská pevnost Británie na hřebeni Hadriánova valu (UNESCO) — kasárna, sýpky i nejstarší dochované latríny v zemi. Val se odsud vlní po útesech Whin Sill jako kamenný had; krátká procházka po hradbě je povinnost.', 55.0130, -2.3310, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hadrians%20Wall%20from%20Housesteads1%20crop.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hadrians%20Wall%20from%20Housesteads1%20crop.jpg"}'::text[], 0),
    (v_route, 'Alnwick Castle', 'Druhý největší obývaný hrad Anglie, sídlo vévodů z Northumberlandu — filmové Bradavice, kde Harry Potter poprvé letěl na koštěti. Vedle hradu vyrostla velkolepá zahrada Alnwick Garden s jedovou zahradou za mřížemi.', 55.4156, -1.7060, 'https://commons.wikimedia.org/wiki/Special:FilePath/Alnwick%20Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Alnwick%20Castle.jpg"}'::text[], 1),
    (v_route, 'Restaurace: The Jolly Fisherman (Craster)', 'Hospoda nad miniaturním přístavem proslulá krabí polévkou a výhledem na moře — Craster je domovem legendárních uzených sleďů (kippers) z udírny rodiny Robsonů, funguje tu už od roku 1856. Odsud vede pobřežní pěšina ke zřícenině Dunstanburgh.', 55.4720, -1.5930, 'https://commons.wikimedia.org/wiki/Special:FilePath/Craster%20Harbour.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Craster%20Harbour.jpg"}'::text[], 2),
    (v_route, 'Dunstanburgh Castle', 'Rozeklaná zřícenina hradu ze 14. století na osamělém výběžku, kam nevede žádná silnice — jen půlhodinová procházka po pobřeží z Crasteru mezi pasoucími se ovcemi. Jedna z nejromantičtějších siluet Anglie, milovaná malířem Turnerem.', 55.4900, -1.5940, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dunstanburgh%20Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dunstanburgh%20Castle.jpg"}'::text[], 3),
    (v_route, 'Bamburgh Castle', 'Mohutný hrad na čedičové skále přímo nad plážemi a dunami — bývalé sídlo králů Northumbrie a dnes jedna z nejfotogeničtějších pevností Británie. Silnice podél pláže nabízí ten nejlepší pohled; ve vsi má muzeum viktoriánská hrdinka Grace Darling.', 55.6090, -1.7150, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bamburgh%20Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bamburgh%20Castle.jpg"}'::text[], 4),
    (v_route, 'Lindisfarne (Holy Island)', 'Svatý ostrov, kolébka anglického křesťanství s klášterem vypleněným Vikingy roku 793 a hrádkem na kuželové skále. Přístupová silnice po hrázi se dvakrát denně noří pod příliv — přejíždějte JEN v publikovaných bezpečných časech, uvízlá auta tu tahají každý rok.', 55.6805, -1.8010, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lindisfarne%20Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lindisfarne%20Castle.jpg"}'::text[], 5);
