  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'TT Grandstand (Douglas)', 'Start a cíl závodu TT na Glencrutchery Road — tribuny, ručně obsluhovaná výsledková tabule a památník jezdců. Hned vedle je pomník legendárního Joeyho Dunlopa; tady začíná i vaše kolo okruhu.', 54.1670, -4.4680, 'https://commons.wikimedia.org/wiki/Special:FilePath/Douglas%20Isle%20of%20Man.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Douglas%20Isle%20of%20Man.jpg"}'::text[], 0),
    (v_route, 'Ballaugh Bridge', 'Hrbatý kamenný mostek, na kterém závodníci TT létají metry vysoko — nejslavnější skok okruhu. V civilním provozu přejíždějte krokem; hned u mostu je hospoda Raven, odkud se skoky při závodech sledují nejlépe.', 54.3110, -4.5430, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ballaugh%20Bridge.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ballaugh%20Bridge.jpg"}'::text[], 1),
    (v_route, 'Ramsey', 'Druhé největší město ostrova s přístavem a proslulou vlásenkou Ramsey Hairpin, kde okruh začíná stoupat do hor. Na náměstí Parliament Square se při závodech tvoří legendární atmosféra; dobrá zastávka na kávu před horským úsekem.', 54.3220, -4.3810, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ramsey%20Isle%20of%20Man.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ramsey%20Isle%20of%20Man.jpg"}'::text[], 2),
    (v_route, 'Snaefell Mountain Road (Bungalow)', 'Nejrychlejší část okruhu přes úbočí hory Snaefell (621 m) — na Bungalow kříží silnici historická horská tramvaj, kterou se dá vyjet až na vrchol s výhledem na „sedm království". Mimo obce tu neplatí obecný rychlostní limit, přesto: hlavu chladnou.', 54.2652, -4.4620, 'https://commons.wikimedia.org/wiki/Special:FilePath/Snaefell%20Mountain%20Railway.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Snaefell%20Mountain%20Railway.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Creg-ny-Baa', 'Legendární hospoda v pravotočivé zatáčce sjezdu z hor, jedno z nejslavnějších diváckých míst TT — jídlo s výhledem přímo na trať. Burger „TT" a manská specialita queenies (hřebenatky) jsou sázka na jistotu.', 54.1953, -4.4384, 'https://commons.wikimedia.org/wiki/Special:FilePath/Creg-ny-Baa.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Creg-ny-Baa.jpg"}'::text[], 4),
    (v_route, 'Laxey Wheel', 'Největší funkční vodní kolo světa „Lady Isabella" (průměr 22 m) z roku 1854, které odvodňovalo doly na zinek a olovo. Krátká odbočka z okruhu; z Laxey jezdí na Snaefell i horská železnice.', 54.2360, -4.4010, 'https://commons.wikimedia.org/wiki/Special:FilePath/Laxey%20Wheel.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Laxey%20Wheel.jpg"}'::text[], 5),
    (v_route, 'Peel Castle', 'Rozlehlá hradní zřícenina Vikingů a keltských svatých na ostrůvku St Patrick''s Isle nad rybářským Peelem na západním pobřeží. Ochutnejte místní uzenáče a manskou zmrzlinu na nábřeží; západy slunce jsou odsud nejhezčí na ostrově.', 54.2261, -4.6980, 'https://commons.wikimedia.org/wiki/Special:FilePath/Peel%20Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Peel%20Castle.jpg"}'::text[], 6);
