  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Canterbury – katedrála', 'Matka anglikánské církve a cíl poutníků z Canterburských povídek (UNESCO) — gotická katedrála, kde byl roku 1170 zavražděn arcibiskup Tomáš Becket. Historické centrum s hrázděnými domy se nejlépe projde pěšky, motorku nechte na záchytném parkovišti.', 51.2798, 1.0830, 'https://commons.wikimedia.org/wiki/Special:FilePath/Canterbury%20Cathedral%20-%20Portal%20Nave%20Cross-spire.jpeg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Canterbury%20Cathedral%20-%20Portal%20Nave%20Cross-spire.jpeg"}'::text[], 0),
    (v_route, 'Bílé útesy doverské', 'Symbol Anglie — křídová stěna vysoká přes sto metrů, za jasného dne s výhledem přes Kanál až na francouzské pobřeží. Od návštěvnického centra vede pěšina po hraně k majáku South Foreland; k okraji útesů se nepřibližujte.', 51.1340, 1.3280, 'https://commons.wikimedia.org/wiki/Special:FilePath/White%20cliffs%20of%20dover%2009%202004.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/White%20cliffs%20of%20dover%2009%202004.jpg"}'::text[], 1),
    (v_route, 'Dover Castle', '„Klíč k Anglii" — největší anglický hrad, strážící úžinu od dob Jindřicha II. V křídě pod ním se skrývají válečné tunely, odcizené velení evakuace z Dunkerku v roce 1940; expozice patří k nejlepším v zemi.', 51.1290, 1.3210, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dover%20Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dover%20Castle.jpg"}'::text[], 2),
    (v_route, 'Rye – Mermaid Street', 'Dlážděná ulička lemovaná hrázděnými domy z 15. století — jedna z nejfotogeničtějších ulic Anglie v městečku bývalých pašeráků. Rye kdysi stálo přímo u moře; dnes z citadely shlížíte na míle mokřadů plných ovcí.', 50.9497, 0.7340, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mermaid%20Street,%20Rye.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mermaid%20Street,%20Rye.jpg"}'::text[], 3),
    (v_route, 'Restaurace: The Mermaid Inn (Rye)', 'Legendární hostinec se sklepy z roku 1156 a přestavbou z roku 1420 — doupě pašeráckého gangu Hawkhurst, dnes vyhlášená restaurace s krby a duchy podle místních pověstí. Perfektní oběd v polovině trasy.', 50.9500, 0.7330, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rye,%20East%20Sussex.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rye,%20East%20Sussex.jpg"}'::text[], 4),
    (v_route, 'Beachy Head', 'Nejvyšší křídový útes Británie (162 m) s červenobílým majákem u paty stěny — silnice po mysu od Eastbourne je krátká, ale scénicky velkolepá. Na hraně bývá silný vítr, motorku stavějte proti němu a k okraji nechoďte.', 50.7373, 0.2529, 'https://commons.wikimedia.org/wiki/Special:FilePath/Beachy%20Head%20and%20Lighthouse,%20East%20Sussex,%20England%20-%20April%202010.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Beachy%20Head%20and%20Lighthouse,%20East%20Sussex,%20England%20-%20April%202010.jpg"}'::text[], 5),
    (v_route, 'Seven Sisters', 'Sedm zvlněných křídových útesů mezi Cuckmere Haven a Birling Gap — panorama, které filmaři používají místo Doveru, protože je bez lodí a přístavů. Nejlepší pohled je od pobřežních domků u ústí řeky Cuckmere.', 50.7590, 0.1530, 'https://commons.wikimedia.org/wiki/Special:FilePath/Seven%20Sisters%20cliffs.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Seven%20Sisters%20cliffs.jpg"}'::text[], 6),
    (v_route, 'Brighton Palace Pier', 'Viktoriánské zábavní molo z roku 1899 — symbol nejživějšího přímořského města Anglie s promenádou, pouťovými atrakcemi a fish and chips v papíru. Kousek odtud stojí exotický Royal Pavilion s indickými kupolemi; důstojná tečka za trasou.', 50.8160, -0.1370, 'https://commons.wikimedia.org/wiki/Special:FilePath/Brighton%20Palace%20Pier.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Brighton%20Palace%20Pier.jpg"}'::text[], 7);
