-- ════════════════════════════════════════════════════════════════════
-- MotoGo24 — SEED doporučených tras — VELKÁ BRITÁNIE (10 tras, sort 3910–4000)
-- NEAPLIKOVÁNO na živou DB — přehled a spuštění je na adminovi.
-- Trasy: is_active=false (Skryto) + status='approved' → ve Velíně zkontroluj a Publikuj.
-- Idempotence: každá trasa se před vložením smaže dle (name, branch_id).
-- ════════════════════════════════════════════════════════════════════
alter table public.routes add column if not exists countries text[] not null default '{}'::text[];

do $$
declare
  v_branch uuid;
  v_route  uuid;
begin
  -- Domovská pobočka = nejbližší k Mezné (49.3464, 15.2119); fallback první.
  select id into v_branch from public.branches
    order by (power(coalesce(gps_lat,0)-49.3464,2) + power(coalesce(gps_lng,0)-15.2119,2)) asc
    limit 1;
  if v_branch is null then
    raise exception 'Nenalezena žádná pobočka v public.branches — nelze nasadit trasy.';
  end if;

  -- Anglie – Lake District a průsmyk Hardknott
  delete from public.routes where name = 'Anglie – Lake District a průsmyk Hardknott' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Anglie – Lake District a průsmyk Hardknott', 'Jezerní okruh z Keswicku je koncentrát toho nejlepšího z anglického Lake Districtu: úzké silničky mezi kamennými zídkami, zrcadlící se jezera a dva nejstrmější asfaltové průsmyky Anglie — Hardknott a Wrynose se sklonem až 30 % a vlásenkami jako z Alp v kapesním vydání. Přes Honister Pass sjedete k jezeru Buttermere, údolím Eskdale vystoupáte na Hardknott s římskou pevností a přes Ambleside a Kirkstone Pass se vrátíte zpět. POZOR: v celé Británii se jezdí VLEVO — na jednoproudých úsecích s výhybnami (passing places) buďte trpěliví a pouštějte protijedoucí. Nejlepší je květen až září, mimo víkendové špičky; povrch je místy hrbolatý a v průsmycích počítejte s ovcemi na vozovce a s rychle se měnícím počasím. Na kávu a výborné jídlo zastavte v Ambleside.', 'loop', 175, 330, 'hard',
     '[{"lat": 54.6013, "lng": -3.1347, "label": "Start: Keswick"}, {"lat": 54.5116, "lng": -3.1994, "label": "Honister Pass"}, {"lat": 54.5417, "lng": -3.2766, "label": "Buttermere"}, {"lat": 54.4029, "lng": -3.2116, "label": "Hardknott Pass"}, {"lat": 54.4287, "lng": -2.9613, "label": "Ambleside"}, {"lat": 54.4700, "lng": -2.9265, "label": "Kirkstone Pass"}, {"lat": 54.6013, "lng": -3.1347, "label": "Cíl: Keswick"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=54.6013,-3.1347&destination=54.6013,-3.1347&travelmode=driving&waypoints=54.5116,-3.1994%7C54.5417,-3.2766%7C54.4029,-3.2116%7C54.4287,-2.9613%7C54.4700,-2.9265', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ashness%20Bridge,%20Lake%20District%20-%20June%202009.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ashness%20Bridge,%20Lake%20District%20-%20June%202009.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Honister%20Pass.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Buttermere,%20Lake%20District%20-%20June%202009.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hardknott%20Pass.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Wrynose%20Pass.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bridge%20House,%20Ambleside.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kirkstone%20Pass.jpg"}'::text[], '{"Ashness Bridge","Honister Pass","Buttermere","Hardknott Pass","Wrynose Pass","Restaurace: The Old Stamp House (Ambleside)","Kirkstone Pass"}'::text[], '{"GB"}'::text[], false, 3910, 'approved');

  -- Anglie – Yorkshire Dales a Buttertubs Pass
  delete from public.routes where name = 'Anglie – Yorkshire Dales a Buttertubs Pass' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Anglie – Yorkshire Dales a Buttertubs Pass', 'Okruh národním parkem Yorkshire Dales z městečka Hawes spojuje to, co Angličané milují: vřesoviště, kamenné zídky táhnoucí se po horizont a rychlé, přehledné silnice s výhledy. Buttertubs Pass označil Jeremy Clarkson za jednu z nejlepších silnic Anglie, u Tan Hill se zastavíte v nejvýše položené hospodě Británie a pod viaduktem Ribblehead pochopíte, proč sem jezdí fotografové z celého světa. Přes vápencový amfiteátr Malham Cove a vodopády Aysgarth se vrátíte zpět do Wensleydale, domoviny slavného sýra. Jezdí se VLEVO a na jednoproudých úsecích čekejte výhybny, ovce a o víkendech cyklisty. Ideální od dubna do října; na otevřených vřesovištích umí pořádně foukat.', 'loop', 190, 300, 'medium',
     '[{"lat": 54.3040, "lng": -2.1980, "label": "Start: Hawes"}, {"lat": 54.3450, "lng": -2.2010, "label": "Buttertubs Pass"}, {"lat": 54.4426, "lng": -2.1631, "label": "Tan Hill"}, {"lat": 54.2107, "lng": -2.3703, "label": "Ribblehead"}, {"lat": 54.0722, "lng": -2.1580, "label": "Malham"}, {"lat": 54.2919, "lng": -1.9819, "label": "Aysgarth"}, {"lat": 54.3040, "lng": -2.1980, "label": "Cíl: Hawes"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=54.3040,-2.1980&destination=54.3040,-2.1980&travelmode=driving&waypoints=54.3450,-2.2010%7C54.4426,-2.1631%7C54.2107,-2.3703%7C54.0722,-2.1580%7C54.2919,-1.9819', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ribblehead%20Viaduct.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Buttertubs%20Pass.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Muker,%20Swaledale.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Tan%20Hill%20Inn.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ribblehead%20Viaduct.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Malham%20Cove.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Aysgarth%20Falls.jpg"}'::text[], '{"Buttertubs Pass","Muker (Swaledale)","Restaurace: Tan Hill Inn","Ribblehead Viaduct","Malham Cove","Aysgarth Falls"}'::text[], '{"GB"}'::text[], false, 3920, 'approved');

  -- Anglie – Peak District a Snake Pass
  delete from public.routes where name = 'Anglie – Peak District a Snake Pass' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Anglie – Peak District a Snake Pass', 'Okruh nejstarším národním parkem Anglie začíná v Glossopu proslulou A57 Snake Pass — hadovitou horskou silnicí přes vřesoviště, kterou si motorkáři z Manchesteru a Sheffieldu hlídají jako rodinné stříbro. Kolem přehrad Ladybower sjedete do údolí Hope Valley, projedete dramatickou vápencovou soutěskou Winnats Pass nad Castletonem a přes panství Chatsworth dorazíte do Matlock Bath — viktoriánského lázeňského městečka, které je o víkendech neoficiálním srazem motorkářů z celé Anglie. Jezdí se VLEVO; na Snake Pass pozor na zvlněný povrch, boční vítr a o víkendech na policejní měření. Nejlépe ve všední den od jara do podzimu, v zimě bývá průsmyk zavřený kvůli sněhu.', 'loop', 150, 240, 'medium',
     '[{"lat": 53.4432, "lng": -1.9490, "label": "Start: Glossop"}, {"lat": 53.4326, "lng": -1.8560, "label": "Snake Pass"}, {"lat": 53.3780, "lng": -1.7130, "label": "Ladybower"}, {"lat": 53.3436, "lng": -1.7767, "label": "Castleton"}, {"lat": 53.2277, "lng": -1.6110, "label": "Chatsworth"}, {"lat": 53.1220, "lng": -1.5610, "label": "Matlock Bath"}, {"lat": 53.4432, "lng": -1.9490, "label": "Cíl: Glossop"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=53.4432,-1.9490&destination=53.4432,-1.9490&travelmode=driving&waypoints=53.4326,-1.8560%7C53.3780,-1.7130%7C53.3436,-1.7767%7C53.2277,-1.6110%7C53.1220,-1.5610', 'https://commons.wikimedia.org/wiki/Special:FilePath/Winnats%20Pass.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Snake%20Pass.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ladybower%20Reservoir.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Winnats%20Pass.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Peveril%20Castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Chatsworth%20House.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Matlock%20Bath.jpg"}'::text[], '{"Snake Pass (A57)","Ladybower Reservoir","Winnats Pass","Castleton a Peveril Castle","Chatsworth House","Matlock Bath"}'::text[], '{"GB"}'::text[], false, 3930, 'approved');

  -- Anglie – Cat and Fiddle a Goytské údolí
  delete from public.routes where name = 'Anglie – Cat and Fiddle a Goytské údolí' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Anglie – Cat and Fiddle a Goytské údolí', 'Krátký, ale intenzivní okruh po západním okraji Peak Districtu kolem silnice A537 Macclesfield–Buxton, které nikdo neřekne jinak než „Cat and Fiddle" podle hospody na jejím vrcholu. Sedm mil zatáček s výhledy na Cheshirskou nížinu patří k nejslavnějším motorkářským silnicím Británie — a také k nejhlídanějším, takže průměrové kamery berte vážně a užívejte si rytmus, ne rychlost. Z lázeňského Buxtonu pokračujete po neméně zábavné A53 kolem skalního hřebene The Roaches a přes Wildboarclough pod „cheshirským Matterhornem" Shutlingsloe zpět. Jezdí se VLEVO; na vřesovištích počítejte s větrem, mlhou a volně pobíhajícími ovcemi. Ideální brzy ráno ve všední den, od jara do podzimu.', 'loop', 105, 180, 'medium',
     '[{"lat": 53.2587, "lng": -2.1256, "label": "Start: Macclesfield"}, {"lat": 53.2437, "lng": -1.9967, "label": "Cat and Fiddle"}, {"lat": 53.2591, "lng": -1.9110, "label": "Buxton"}, {"lat": 53.1650, "lng": -1.9930, "label": "The Roaches"}, {"lat": 53.2317, "lng": -2.0090, "label": "Wildboarclough"}, {"lat": 53.2587, "lng": -2.1256, "label": "Cíl: Macclesfield"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=53.2587,-2.1256&destination=53.2587,-2.1256&travelmode=driving&waypoints=53.2437,-1.9967%7C53.2591,-1.9110%7C53.1650,-1.9930%7C53.2317,-2.0090', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20and%20Fiddle%20Inn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20and%20Fiddle%20Inn.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Errwood%20Reservoir.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/The%20Crescent,%20Buxton.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Buxton%20Opera%20House.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/The%20Roaches.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Shutlingsloe.jpg"}'::text[], '{"Cat and Fiddle Inn","Errwood Reservoir (Goyt Valley)","Buxton – The Crescent","Restaurace: The Old Hall Hotel (Buxton)","The Roaches","Shutlingsloe"}'::text[], '{"GB"}'::text[], false, 3940, 'approved');

  -- Anglie – Cotswolds, medové vesnice
  delete from public.routes where name = 'Anglie – Cotswolds, medové vesnice' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Anglie – Cotswolds, medové vesnice', 'Pohodový okruh krajinou Cotswolds, kde je každá vesnice postavená z medově zbarveného vápence a vypadá jako kulisa historického filmu. Z Burfordu se svezete k nejfotografovanější uličce Anglie — Arlington Row v Bibury — projedete „anglické Benátky" Bourton-on-the-Water, tržní městečka Stow-on-the-Wold a Chipping Campden a vystoupáte k romantické vyhlídkové věži Broadway Tower. Silnice jsou tu klidné, zvlněné a přehledné, ideální i pro méně zkušené jezdce nebo jízdu ve dvou. Jezdí se VLEVO; pozor na úzké uličky v centrech vesnic, projíždějící traktory a víkendové davy turistů — Bibury je nejhezčí brzy ráno. Krásné je to od jara do podzimu, v říjnu se buky barví dozlatova.', 'loop', 120, 210, 'easy',
     '[{"lat": 51.8085, "lng": -1.6362, "label": "Start: Burford"}, {"lat": 51.7599, "lng": -1.8330, "label": "Bibury"}, {"lat": 51.8523, "lng": -1.7550, "label": "Bourton-on-the-Water"}, {"lat": 51.9300, "lng": -1.7220, "label": "Stow-on-the-Wold"}, {"lat": 52.0244, "lng": -1.8358, "label": "Broadway Tower"}, {"lat": 52.0500, "lng": -1.7790, "label": "Chipping Campden"}, {"lat": 51.8085, "lng": -1.6362, "label": "Cíl: Burford"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=51.8085,-1.6362&destination=51.8085,-1.6362&travelmode=driving&waypoints=51.7599,-1.8330%7C51.8523,-1.7550%7C51.9300,-1.7220%7C52.0244,-1.8358%7C52.0500,-1.7790', 'https://commons.wikimedia.org/wiki/Special:FilePath/Arlington%20Row,%20Bibury.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Burford%20High%20Street.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Arlington%20Row,%20Bibury.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bourton-on-the-Water.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Stow-on-the-Wold.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Broadway%20tower%20edit.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Broadway,%20Worcestershire.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Chipping%20Campden%20High%20Street.jpg"}'::text[], '{"Burford","Bibury – Arlington Row","Bourton-on-the-Water","Stow-on-the-Wold","Broadway Tower","Restaurace: The Lygon Arms (Broadway)","Chipping Campden"}'::text[], '{"GB"}'::text[], false, 3950, 'approved');

  -- Anglie – Cornwall a Land's End
  delete from public.routes where name = 'Anglie – Cornwall a Land''s End' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Anglie – Cornwall a Land''s End', 'Okruh úplným koncem Anglie: z Penzance kolem pohádkového ostrovního zámku St Michael''s Mount na nejjižnější bod Británie Lizard Point, a poté přes rybářský Mousehole a divadlo Minack vytesané do útesu až na slavný mys Land''s End. Zpáteční cesta vede přes bývalé hornické pobřeží u St Just do uměleckého přístavu St Ives s tyrkysovou vodou jako z Karibiku. Kornwallské silničky jsou úzké, lemované vysokými živými ploty a plné slepých zatáček — jezdí se VLEVO, takže houkněte klaksonem před nepřehlednou zúženinou a počítejte s couváním k výhybně. Nejkrásněji je tu v květnu a červnu nebo v září, o letních prázdninách oblast praská ve švech. Vůně moře, pastis a čerstvé krabí sendviče k téhle trase patří.', 'loop', 160, 300, 'medium',
     '[{"lat": 50.1188, "lng": -5.5376, "label": "Start: Penzance"}, {"lat": 50.1170, "lng": -5.4770, "label": "Marazion – St Michael''s Mount"}, {"lat": 49.9591, "lng": -5.2151, "label": "Lizard Point"}, {"lat": 50.0403, "lng": -5.6519, "label": "Porthcurno – Minack"}, {"lat": 50.0664, "lng": -5.7147, "label": "Land''s End"}, {"lat": 50.2110, "lng": -5.4800, "label": "St Ives"}, {"lat": 50.1188, "lng": -5.5376, "label": "Cíl: Penzance"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.1188,-5.5376&destination=50.1188,-5.5376&travelmode=driving&waypoints=50.1170,-5.4770%7C49.9591,-5.2151%7C50.0403,-5.6519%7C50.0664,-5.7147%7C50.2110,-5.4800', 'https://commons.wikimedia.org/wiki/Special:FilePath/St%20Michael''s%20Mount.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/St%20Michael''s%20Mount.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lizard%20Point,%20Cornwall.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Mousehole%20Harbour.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Minack%20Theatre.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Land''s%20End.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/St%20Ives%20Cornwall.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/The%20Sloop%20Inn,%20St%20Ives.jpg"}'::text[], '{"St Michael''s Mount","Lizard Point","Mousehole","Minack Theatre","Land''s End","St Ives","Restaurace: The Sloop Inn (St Ives)"}'::text[], '{"GB"}'::text[], false, 3960, 'approved');

  -- Anglie – Devon a národní park Dartmoor
  delete from public.routes where name = 'Anglie – Devon a národní park Dartmoor' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Anglie – Devon a národní park Dartmoor', 'Okruh z Exeteru přes tajemný Dartmoor — největší divočinu jižní Anglie, kde se mezi žulovými skalisky (tory) volně pasou poníci a krajina inspirovala Psa baskervillského. Silnice B3212 napříč vřesovištěm patří k nejhezčím v Devonu: otevřené výhledy, plynulé zatáčky a středověké kamenné mosty v Postbridge a Dartmeetu. Zastavíte u skalní věže Haytor, ve vesničce Widecombe-in-the-Moor i u kostelíka na sopečném suku Brent Tor, odkud je vidět půlka hrabství. Jezdí se VLEVO a zdejší poníci ani ovce silnici nikomu neuhýbají — v mlze, která umí spadnout během minut, jeďte opravdu opatrně. Nejlepší od května do října; v srpnu vřesoviště fialoví.', 'loop', 145, 250, 'medium',
     '[{"lat": 50.7236, "lng": -3.5275, "label": "Start: Exeter"}, {"lat": 50.5800, "lng": -3.7530, "label": "Haytor"}, {"lat": 50.5761, "lng": -3.8110, "label": "Widecombe-in-the-Moor"}, {"lat": 50.5920, "lng": -3.9120, "label": "Postbridge"}, {"lat": 50.5540, "lng": -3.9660, "label": "Two Bridges"}, {"lat": 50.6053, "lng": -4.1600, "label": "Brent Tor"}, {"lat": 50.7236, "lng": -3.5275, "label": "Cíl: Exeter"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.7236,-3.5275&destination=50.7236,-3.5275&travelmode=driving&waypoints=50.5800,-3.7530%7C50.5761,-3.8110%7C50.5920,-3.9120%7C50.5540,-3.9660%7C50.6053,-4.1600', 'https://commons.wikimedia.org/wiki/Special:FilePath/Haytor%20Rocks.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Haytor%20Rocks.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Widecombe-in-the-Moor.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dartmeet.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Postbridge%20Clapper%20Bridge.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Two%20Bridges%20Hotel.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dartmoor%20Prison.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Brentor%20Church.jpg"}'::text[], '{"Haytor","Widecombe-in-the-Moor","Dartmeet","Postbridge – Clapper Bridge","Restaurace: Two Bridges Hotel (Dartmoor)","Princetown","Brent Tor"}'::text[], '{"GB"}'::text[], false, 3970, 'approved');

  -- Anglie – Northumberland, hrady a Hadriánův val
  delete from public.routes where name = 'Anglie – Northumberland, hrady a Hadriánův val' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Anglie – Northumberland, hrady a Hadriánův val', 'Cesta nejméně zalidněným hrabstvím Anglie od římského Hadriánova valu k hradům na břehu Severního moře. Z Corbridge vyjedete podél valu k pevnosti Housesteads, pak prázdnými silnicemi přes vřesoviště Northumberlandu na pobřeží: filmový Alnwick (Bradavice z Harryho Pottera), rybářský Craster s vyhlášenými uzenými sledi, romantická zřícenina Dunstanburgh a majestátní Bamburgh Castle na skále nad plážovými dunami. Finále patří ostrovu Lindisfarne, na který vede silnice zaplavovaná přílivem — časy bezpečného přejezdu si POVINNĚ ověřte předem. Jezdí se VLEVO; silnice jsou tu širší a prázdnější než jinde v Anglii, ideální na plynulé tempo. Nejlépe květen až září, od moře ale i v létě fouká chladný vítr.', 'poi', 185, 280, 'easy',
     '[{"lat": 54.9740, "lng": -2.0180, "label": "Start: Corbridge"}, {"lat": 55.0130, "lng": -2.3310, "label": "Housesteads"}, {"lat": 55.4156, "lng": -1.7060, "label": "Alnwick"}, {"lat": 55.4720, "lng": -1.5930, "label": "Craster"}, {"lat": 55.6090, "lng": -1.7150, "label": "Bamburgh"}, {"lat": 55.6805, "lng": -1.8010, "label": "Cíl: Lindisfarne"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=54.9740,-2.0180&destination=55.6805,-1.8010&travelmode=driving&waypoints=55.0130,-2.3310%7C55.4156,-1.7060%7C55.4720,-1.5930%7C55.6090,-1.7150', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bamburgh%20Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hadrians%20Wall%20from%20Housesteads1%20crop.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Alnwick%20Castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Craster%20Harbour.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dunstanburgh%20Castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bamburgh%20Castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lindisfarne%20Castle.jpg"}'::text[], '{"Hadriánův val – Housesteads","Alnwick Castle","Restaurace: The Jolly Fisherman (Craster)","Dunstanburgh Castle","Bamburgh Castle","Lindisfarne (Holy Island)"}'::text[], '{"GB"}'::text[], false, 3980, 'approved');

  -- Isle of Man – okruh TT Mountain Course
  delete from public.routes where name = 'Isle of Man – okruh TT Mountain Course' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Isle of Man – okruh TT Mountain Course', 'Svatá pouť každého motorkáře: objet 60 km dlouhý Mountain Course, na kterém se od roku 1907 jezdí nejslavnější a nejnebezpečnější silniční závod světa — Isle of Man TT. Od tribun TT Grandstand v Douglasu projedete Ballacraine a Kirk Michael, skočíte (pomalu!) přes hrbatý mostek v Ballaugh, otočíte se na náměstí v Ramsey a vystoupáte horským úsekem kolem Snaefellu k legendární zatáčce Creg-ny-Baa. Na ostrov se dostanete trajektem z Liverpoolu nebo Heyshamu; jezdí se VLEVO a na horském úseku mimo obce NENÍ obecný rychlostní limit — o to větší sebekázeň je na místě, silnice je obousměrná a zrádná. Mimo závodní týdny (přelom května a června) je okruh příjemně prázdný; přidejte si odbočku k obřímu vodnímu kolu v Laxey a k hradu Peel. Počasí se nad Snaefellem mění bleskově.', 'loop', 105, 180, 'medium',
     '[{"lat": 54.1670, "lng": -4.4680, "label": "Start: Douglas (TT Grandstand)"}, {"lat": 54.3110, "lng": -4.5430, "label": "Ballaugh Bridge"}, {"lat": 54.3220, "lng": -4.3810, "label": "Ramsey"}, {"lat": 54.2652, "lng": -4.4620, "label": "Bungalow (Snaefell)"}, {"lat": 54.1953, "lng": -4.4384, "label": "Creg-ny-Baa"}, {"lat": 54.2360, "lng": -4.4010, "label": "Laxey"}, {"lat": 54.1670, "lng": -4.4680, "label": "Cíl: Douglas"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=54.1670,-4.4680&destination=54.1670,-4.4680&travelmode=driving&waypoints=54.3110,-4.5430%7C54.3220,-4.3810%7C54.2652,-4.4620%7C54.1953,-4.4384%7C54.2360,-4.4010', 'https://commons.wikimedia.org/wiki/Special:FilePath/Douglas%20Isle%20of%20Man.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Douglas%20Isle%20of%20Man.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ballaugh%20Bridge.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ramsey%20Isle%20of%20Man.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Snaefell%20Mountain%20Railway.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Creg-ny-Baa.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Laxey%20Wheel.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Peel%20Castle.jpg"}'::text[], '{"TT Grandstand (Douglas)","Ballaugh Bridge","Ramsey","Snaefell Mountain Road (Bungalow)","Restaurace: Creg-ny-Baa","Laxey Wheel","Peel Castle"}'::text[], '{"GB","IM"}'::text[], false, 3990, 'approved');

  -- Anglie – Kent a Sussex, bílé útesy
  delete from public.routes where name = 'Anglie – Kent a Sussex, bílé útesy' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Anglie – Kent a Sussex, bílé útesy', 'Pobřežní cesta „zahradou Anglie" z katedrálního Canterbury do bohémského Brightonu, po trase křídových útesů, chmelnic a středověkých přístavů. Nad Doverem se projdete po hraně slavných bílých útesů s výhledem na Francii, ve středověkém Rye zaparkujete pod hrázděnými domy dlážděné Mermaid Street a přes větrné mysy Beachy Head a Seven Sisters dojedete na promenádu v Brightonu. Silnice jsou nenáročné a scenérie velkolepé — ideální trasa na první seznámení s ježděním VLEVO, klidně hned po příjezdu trajektem či Eurotunelem do Doveru. Pozor na hustý provoz kolem přístavů a na silný boční vítr na útesech; k okrajům útesů nechoďte, křída se bortí. Krásné celoročně, nejlépe květen–září.', 'poi', 185, 280, 'easy',
     '[{"lat": 51.2798, "lng": 1.0830, "label": "Start: Canterbury"}, {"lat": 51.1340, "lng": 1.3280, "label": "Dover"}, {"lat": 50.9500, "lng": 0.7330, "label": "Rye"}, {"lat": 50.7373, "lng": 0.2529, "label": "Beachy Head"}, {"lat": 50.7590, "lng": 0.1530, "label": "Seven Sisters"}, {"lat": 50.8225, "lng": -0.1372, "label": "Cíl: Brighton"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=51.2798,1.0830&destination=50.8225,-0.1372&travelmode=driving&waypoints=51.1340,1.3280%7C50.9500,0.7330%7C50.7373,0.2529%7C50.7590,0.1530', 'https://commons.wikimedia.org/wiki/Special:FilePath/Canterbury%20Cathedral%20-%20Portal%20Nave%20Cross-spire.jpeg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Canterbury%20Cathedral%20-%20Portal%20Nave%20Cross-spire.jpeg","https://commons.wikimedia.org/wiki/Special:FilePath/White%20cliffs%20of%20dover%2009%202004.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dover%20Castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Mermaid%20Street,%20Rye.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rye,%20East%20Sussex.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Beachy%20Head%20and%20Lighthouse,%20East%20Sussex,%20England%20-%20April%202010.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Seven%20Sisters%20cliffs.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Brighton%20Palace%20Pier.jpg"}'::text[], '{"Canterbury – katedrála","Bílé útesy doverské","Dover Castle","Rye – Mermaid Street","Restaurace: The Mermaid Inn (Rye)","Beachy Head","Seven Sisters","Brighton Palace Pier"}'::text[], '{"GB"}'::text[], false, 4000, 'approved');

